package io.lumine.mythic.lib.script.condition.generic;import io.lumine.mythic.lib.script.condition.RawCondition;import io.lumine.mythic.lib.util.configobject.ConfigObject;public class HasVariableCondition extends RawCondition{public HasVariableCondition(ConfigObject c){super("has_variable"+render(c));}private static String render(ConfigObject c){if(c==null||c.getKeys().isEmpty())return "";StringBuilder b=new StringBuilder("{");boolean first=true;for(String k:c.getKeys()){if(!first)b.append(';');first=false;b.append(k).append('=').append(c.getString(k,""));}return b.append('}').toString();}}